#include <unistd.h>
#include <sys/types.h>
#include <linux/unistd.h>
#include <linux/ucred.h>

int can_send_creds(struct ucred *creds) {
    uid_t euid = geteuid();
    gid_t egid = getegid();

    // Check if the provided credentials match the current process's
    // effective user and group IDs.
    if (creds->uid != euid || creds->gid != egid) {
        // Check if the current process has administrative capabilities.
        if (euid != 0) {
            return -EPERM;
        }
    }

    // Validate the UID and GID values.
    if (creds->uid == (uid_t)(-1) || creds->gid == (gid_t)(-1)) {
        return -EINVAL;
    }

    return 0;
}

int check_creds_sendability(struct ucred *creds) {
    uid_t euid = geteuid();
    gid_t egid = getegid();

    if (creds->uid != euid && creds->gid != egid && !capable(CAP_SYS_ADMIN)) {
        return -EPERM;
    }

    if (creds->uid == INVALID_UID || creds->gid == INVALID_GID) {
        return -EINVAL;
    }

    return 0;
}

#include <unistd.h>
#include <sys/types.h>
#include <sys/credentials.h>

int can_send_credentials(struct ucred *creds) {
    uid_t euid = geteuid();
    gid_t egid = getegid();

    // Check if the provided credentials are valid
    if (creds == NULL) {
        return -EINVAL;
    }

    // Check if the provided UID and GID are valid
    if (creds->uid < 0 || creds->gid < 0) {
        return -EINVAL;
    }

    // Check if credentials match current process's effective UID and GID
    // or if the current process has administrative capabilities
    if ((creds->uid == euid && creds->gid == egid) || (euid == 0)) {
        return 0;
    }

    return -EPERM;
}

#include <unistd.h>
#include <sys/types.h>
#include <linux/cred.h>
#include <sys/capability.h>
#include <errno.h>

int can_send_creds(struct ucred *creds) {
    uid_t uid = getuid();
    gid_t gid = getgid();
    cap_t caps = cap_get_proc();
    int has_admin_caps = 0;

    if (creds == NULL) {
        return -EINVAL;
    }

    if ((creds->uid == uid && creds->gid == gid) || 
        (caps && cap_get_flag(caps, CAP_SYS_ADMIN, CAP_PERMITTED, &has_admin_caps) == 0 && has_admin_caps)) {
        if (caps)
            cap_free(caps);
        return 0;
    }

    if (caps)
        cap_free(caps);

    return (creds->uid != uid || creds->gid != gid) ? -EINVAL : -EPERM;
}

#include <unistd.h>
#include <sys/types.h>
#include <linux/errno.h>

int check_credentials_send(struct ucred *creds) {
    uid_t uid = getuid();
    uid_t euid = geteuid();
    gid_t gid = getgid();

    if (creds->uid != uid && creds->uid != euid) {
        return -EINVAL;
    }

    if (creds->gid != gid) {
        return -EINVAL;
    }

    if (geteuid() != 0) {
        return -EPERM;
    }

    return 0;
}
